@startuml

class Agency {
  + Search(key: string) : List<Property>
}

class Property {
  + code: string
  + address: string
  + zipCode: string
  + city: string
  + area: int
  + ToString() : string
  + Write() : void
  + Contains(key: string) : boolean
}

class Garage extends Property {
  + numberOfParkingSpaces: int
  + ToString() : string
  + Write() : void
  + Contains(key: string) : boolean
}

class Apartment extends Property {
  + numberOfRooms: int
  + numberOfBathrooms: int
  + ToString() : string
  + Write() : void
  + Contains(key: string) : boolean
}

class Villa extends Apartment {
  + garden: int
  + ToString() : string
  + Write() : void
  + Contains(key: string) : boolean
}

Agency "1" --> "*" Property

@enduml

